import { ref, computed, unref } from 'vue';
import { userAlertApi } from './user-alert-api';

export function useUserAlerts(userId, currentRoute = null) {
    // Persist dismissed alert IDs in sessionStorage - separate for banners and modals
    const BANNER_STORAGE_KEY = 'adminUserAlertDismissedBannerIds';
    const MODAL_STORAGE_KEY = 'adminUserAlertDismissedModalIds';

    function loadDismissedIds(storageKey) {
        try {
            const raw = sessionStorage.getItem(storageKey);
            if (raw) {
                return new Set(JSON.parse(raw));
            }
        } catch (e) { /* ignore */ }
        return new Set();
    }

    function saveDismissedIds(set, storageKey) {
        try {
            sessionStorage.setItem(storageKey, JSON.stringify(Array.from(set)));
        } catch (e) { /* ignore */ }
    }

    const alerts = ref([]);
    const dismissedBannerIds = ref(loadDismissedIds(BANNER_STORAGE_KEY));
    const dismissedModalIds = ref(loadDismissedIds(MODAL_STORAGE_KEY));
    const loading = ref(false);
    const error = ref(null);

    const bannerAlerts = computed(() =>
        alerts.value
            .filter(a => ['banner', 'both'].includes(a.presentation_type))
            .filter(a => !dismissedBannerIds.value.has(a.id))
    );

    const modalAlerts = computed(() =>
        alerts.value
            .filter(a => ['modal', 'both'].includes(a.presentation_type))
            .filter(a => !dismissedModalIds.value.has(a.id))
    );

    async function fetchAlerts() {
        loading.value = true;
        error.value = null;

        try {
            // Unwrap refs/computed to get current values
            const resolvedUserId = unref(userId);
            const resolvedRoute = unref(currentRoute);

            const response = await userAlertApi.getAlertsForUserByRoute(resolvedUserId, resolvedRoute);
            alerts.value = response.data?.alerts || [];
        } catch (err) {
            error.value = err;
            console.error('Failed to fetch user alerts:', err);
        } finally {
            loading.value = false;
        }
    }

    async function dismissAlert(alertId, type = 'both') {
        if (type === 'banner' || type === 'both') {
            // Create a new Set to trigger Vue reactivity
            dismissedBannerIds.value = new Set([...dismissedBannerIds.value, alertId]);
            saveDismissedIds(dismissedBannerIds.value, BANNER_STORAGE_KEY);
        }

        if (type === 'modal' || type === 'both') {
            // Create a new Set to trigger Vue reactivity
            dismissedModalIds.value = new Set([...dismissedModalIds.value, alertId]);
            saveDismissedIds(dismissedModalIds.value, MODAL_STORAGE_KEY);
        }
    }

    return {
        alerts,
        bannerAlerts,
        modalAlerts,
        loading,
        error,
        fetchAlerts,
        dismissAlert,
    };
}

