import { ref } from 'vue';

// Drives DataTablePaginated server-side: each page/sort/filter change refetches a
// single page from the backend. No client-side row cap — the backend returns
// { data, total } for the requested window.
//
// fetchFn receives { page, perPage, sortField, sortOrder, search } and resolves to
// { data, total, ... }. Extra keys on the response are returned from load().
export function useServerTable(fetchFn, opts = {}) {
  const rows = ref([]);
  const total = ref(0);
  const loading = ref(false);
  const sortField = ref(opts.sortField ?? null);
  const sortOrder = ref(opts.sortOrder ?? -1);
  const rowsPerPage = ref(opts.rowsPerPage ?? 10);
  const currentPage = ref(1);
  const search = ref('');

  const load = async () => {
    loading.value = true;
    try {
      const res = await fetchFn({
        page: currentPage.value,
        perPage: rowsPerPage.value,
        sortField: sortField.value,
        sortOrder: sortOrder.value,
        search: search.value,
      });
      rows.value = res?.data ?? [];
      total.value = res?.total ?? 0;
      return res;
    } finally {
      loading.value = false;
    }
  };

  const onPage = (e) => {
    currentPage.value = e.page ?? 1;
    rowsPerPage.value = e.rowsPerPage ?? rowsPerPage.value;
    load();
  };
  const onSort = (e) => {
    sortField.value = e.sortField;
    sortOrder.value = e.sortOrder;
    currentPage.value = 1;
    load();
  };
  const onFilters = (f) => {
    search.value = f?.global?.value ?? '';
    currentPage.value = 1;
    load();
  };
  const reload = () => {
    currentPage.value = 1;
    return load();
  };

  return { rows, total, loading, currentPage, rowsPerPage, sortField, sortOrder, onPage, onSort, onFilters, reload, load };
}

