import { defineStore } from 'pinia';
import { ref } from 'vue';

export const useSecureFileStore = defineStore('secureFile', () => {
    const uploading = ref(false);
    const file = ref(null);
    const fileKey = ref(null);
    const fileUploaded = ref(null);
    const fileDeleted = ref(null);
    const preSignedUploadUrl = ref(null);

    const fetchWithCsrf = (url, options) => {
        return fetch(url, {
            ...options,
            headers: {
                "Content-Type": "application/json",
                Accept: "application/json",
                "X-CSRF-TOKEN": document
                    .querySelector('meta[name="csrf-token"]')
                    .getAttribute("content"),
            },
            credentials: "same-origin",
        });
    };

    const setupUpload = async () => {
        const response = await fetchWithCsrf("/api/sdl/make-upload", {
            method: "POST",
            body: JSON.stringify({
                filename: file.value.name,
                mimeType: file.value.type,
            }),
        });

        if (!response.ok) {
            throw new Error("File upload failed");
        }

        const data = await response.json();
        preSignedUploadUrl.value = data.url;
        fileKey.value = data.key;
    };

    const uploadFile = async () => {
        const response = await fetch(preSignedUploadUrl.value, {
            method: "PUT",
            body: file.value,
        });

        if (!response.ok) {
            throw new Error("File upload failed");
        }
    };

    const persistFile = async () => {
        const response = await fetchWithCsrf("/api/sdl/persist", {
            method: "POST",
            body: JSON.stringify({
                key: fileKey.value,
            }),
        });

        if (!response.ok) {
            throw new Error("File persist failed");
        }
    };

    const deleteFile = async (key) => {
        const response = await fetchWithCsrf(`/api/sdl/delete`, {
            method: "DELETE",
            body: JSON.stringify({
                key: key,
            }),
        });

        if (!response.ok) {
            throw new Error("File delete failed");
        }

        useSecureFileStore().$patch({ fileDeleted: key });
    };

    const handleUpload = async (event) => {
        file.value = event.target.files[0];
        uploading.value = true;

        try {
            await setupUpload();
            await uploadFile();
            await persistFile();
            useSecureFileStore().$patch({ fileUploaded: fileKey.value });
        } catch (error) {
            useSecureFileStore().$patch({ fileUploaded: "failed" });
            console.error(error);
        } finally {
            uploading.value = false;
        }
    };

    return {
        handleUpload,
        deleteFile,
        uploading,
        fileUploaded,
        fileDeleted,
    };
});

