import { defineStore } from 'pinia';
import axios from 'axios';

export const useReconditioningStore = defineStore('reconditioning', {
    state: () => ({
        items: []
    }),
    actions: {
        async fetchItems(listingId) {
            try {
                const index = `/api/reconditioning-items?listingId=${listingId}`;
                const response = await axios.get(index);
                this.items = response.data;
            } catch (error) {
                console.error('Error fetching items:', error);
            }
        },
        async createItem(item) {
            await axios.post('/api/reconditioning-items', item);
            this.items.push(item);
        },
        async deleteItem(label, listingId) {
            try {
                await axios.delete('/api/reconditioning-items',
                    {data: { label, listingId }}
                );
                this.items = this.items.filter(item => item.label !== label);
            } catch (error) {
                console.error('Error deleting item:', error);
            }
        }
    }
});
